sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
(function executeRule(current, gForm, gSNC) {
    function checkDateConflict() {
        var curso = gForm.getValue('course');  // Substitua pelo nome correto do campo
        var dataTreinamento = gForm.getValue('training_date');

        if (!curso || !dataTreinamento) {
            return;
        }

        var ga = new GlideAjax('CheckTrainingDate');
        ga.addParam('sysparm_name', 'checkDateConflict');
        ga.addParam('sysparm_curso', curso);
        ga.addParam('sysparm_data', dataTreinamento);

        ga.getXMLAnswer(function(response) {
            if (response == "conflict") {
                gForm.clearValue('training_date');  // Limpa a data inválida
                gForm.addErrorMessage('Já existe um treinamento para esse curso nessa data. Escolha outra.');
            }
        });
    }

    checkDateConflict();
})(current, gForm, gSNC);

}
